UPDATE tb_adviser 
SET gmt_modify = now()

    , name = #{name}


    , phone = #{phone}


    , email = #{email}


    , state = #{state}


    , image_url = #{imageUrl}


    , region_id = #{regionId}


    , oper_userid = #{operUserId}

WHERE id = #{id};

